const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Nassau County, NY geometry (approximate bounds)
  const nassauCounty = ee.Geometry.Polygon([
    [-73.70, 40.85],
    [-73.45, 40.85],
    [-73.45, 40.63],
    [-73.70, 40.63],
    [-73.70, 40.85]
  ]);

  // Function to get NO2 data for a given year
  function getNO2Data(year) {
    const startDate = ee.Date.fromYMD(year, 10, 1);
    const endDate = ee.Date.fromYMD(year, 10, 23);

    const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterBounds(nassauCounty)
      .filterDate(startDate, endDate)
      .select('tropospheric_NO2_column_number_density');

    return collection;
  }

  // Get collections for each year
  const col2018 = getNO2Data(2018);
  const col2019 = getNO2Data(2019);
  const col2021 = getNO2Data(2021);

  // Check collection sizes
  const size2018 = col2018.size().getInfo();
  const size2019 = col2019.size().getInfo();
  const size2021 = col2021.size().getInfo();

  console.log(`2018 Images: ${size2018}, 2019 Images: ${size2019}, 2021 Images: ${size2021}`);

  // Check for empty collections
  if (size2018 === 0 || size2019 === 0 || size2021 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate mean NO2 for each period
  function calculateMean(collection) {
    const meanImage = collection.mean();
    const stats = meanImage.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: nassauCounty,
      scale: 1000,
      maxPixels: 1e9
    });
    return stats.getInfo();
  }

  const stats2018 = calculateMean(col2018);
  const stats2019 = calculateMean(col2019);
  const stats2021 = calculateMean(col2021);

  const mean2018 = stats2018['tropospheric_NO2_column_number_density'];
  const mean2019 = stats2019['tropospheric_NO2_column_number_density'];
  const mean2021 = stats2021['tropospheric_NO2_column_number_density'];
  const count2018 = stats2018['tropospheric_NO2_column_number_density_count'];
  const count2019 = stats2019['tropospheric_NO2_column_number_density_count'];
  const count2021 = stats2021['tropospheric_NO2_column_number_density_count'];

  console.log(`2018: ${mean2018?.toFixed(6) || 'No data'} (Pixels: ${count2018})`);
  console.log(`2019: ${mean2019?.toFixed(6) || 'No data'} (Pixels: ${count2019})`);
  console.log(`2021: ${mean2021?.toFixed(6) || 'No data'} (Pixels: ${count2021})`);

  // Check for no valid pixels
  if (count2018 === 0 || count2019 === 0 || count2021 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (mean2018 === null || mean2019 === null || mean2021 === null || 
      isNaN(mean2018) || isNaN(mean2019) || isNaN(mean2021)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Validate NO2 values are in reasonable range (molec/cm²)
  if (mean2018 < 0 || mean2019 < 0 || mean2021 < 0 || 
      mean2018 > 1e17 || mean2019 > 1e17 || mean2021 > 1e17) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare values - check if 2021 is lower than both 2018 and 2019
  const isLowerThan2018 = mean2021 < mean2018;
  const isLowerThan2019 = mean2021 < mean2019;

  console.log(`2021 < 2018: ${isLowerThan2018}, 2021 < 2019: ${isLowerThan2019}`);

  if (isLowerThan2018 && isLowerThan2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
